import { gsap } from 'gsap';
import { MeshPhysicalNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { mix, smoothstep, vec3, uv, time, uniform } from 'three/tsl';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const group = new THREE.Group();

  // ============================================================================
  // BACKDROP / STAGE
  // ============================================================================
  const backdropGeom = new THREE.PlaneGeometry(7, 6);
  const backdropMat = new MeshBasicNodeMaterial({
    color: new THREE.Color('#0b0b10'),
    side: THREE.DoubleSide
  });
  const backdrop = new THREE.Mesh(backdropGeom, backdropMat);
  backdrop.position.z = -2.5;
  group.add(backdrop);

  // ============================================================================
  // LIGHTING SETUP
  // ============================================================================
  // Ambient fill
  const ambLight = new THREE.AmbientLight(0xffffff, 0.6);
  group.add(ambLight);

  // Key light (frontal)
  const keyLight = new THREE.DirectionalLight(0xffffff, 1.2);
  keyLight.position.set(1.5, 2.5, 2.0);
  group.add(keyLight);

  // Back rim light (cool, behind-left)
  const rimLight = new THREE.DirectionalLight(0xb0d4ff, 1.0);
  rimLight.position.set(-2.0, 1.5, -2.5);
  group.add(rimLight);

  // ============================================================================
  // PRISM GEOMETRY (Equilateral triangular prism)
  // ============================================================================
  const prismGroup = new THREE.Group();

  const createPrismMesh = () => {
    const geom = new THREE.BufferGeometry();

    const sideLen = 1.2;
    const len = 1.8;
    const h = (sideLen * Math.sqrt(3)) / 2;

    // Triangle vertices (cross-section)
    const v0 = new THREE.Vector3(0, h / 3, 0);
    const v1 = new THREE.Vector3(-sideLen / 2, -h / 3, 0);
    const v2 = new THREE.Vector3(sideLen / 2, -h / 3, 0);

    const halfLen = len / 2;

    // Front face vertices
    const verts = [
      // Front triangle
      v0.clone(), v1.clone(), v2.clone(),
      // Back triangle
      new THREE.Vector3(v0.x, v0.y, halfLen),
      new THREE.Vector3(v1.x, v1.y, halfLen),
      new THREE.Vector3(v2.x, v2.y, halfLen)
    ];

    // Indices: 2 triangles per face + 3 rectangular sides
    const indices = [
      // Front triangle
      0, 1, 2,
      // Back triangle
      3, 5, 4,
      // Side 1 (v0-v1)
      0, 4, 1,
      1, 4, 5,
      // Side 2 (v1-v2)
      1, 5, 2,
      2, 5, 3,
      // Side 3 (v2-v0)
      2, 3, 0,
      0, 3, 4
    ];

    geom.setAttribute('position', new THREE.BufferAttribute(new Float32Array(verts.flatMap(v => [v.x, v.y, v.z])), 3));
    geom.setIndex(new THREE.BufferAttribute(new Uint32Array(indices), 1));
    geom.computeVertexNormals();

    return geom;
  };

  const prismGeom = createPrismMesh();

  // TSL Material with dispersion
  const dispersionAmount = uniform(0.18);
  const dispersionFactorR = uniform(0.0);
  const dispersionFactorG = uniform(0.0);
  const dispersionFactorB = uniform(0.09);

  const prismMat = new MeshPhysicalNodeMaterial({
    color: new THREE.Color(0xffffff),
    transmission: 1.0,
    thickness: 0.9,
    ior: 1.55,
    roughness: 0.08,
    clearcoat: 0.25,
    clearcoatRoughness: 0.1,
    attenuationColor: new THREE.Color('#e8ecf2'),
    attenuationDistance: 2.5,
    iridescence: 1.0,
    iridescenceIOR: 1.3,
    iridescenceThicknessRange: [120, 480]
  });

  const prism = new THREE.Mesh(prismGeom, prismMat);
  prism.rotation.z = THREE.MathUtils.degToRad(12);
  prism.rotation.y = THREE.MathUtils.degToRad(20);
  prismGroup.add(prism);

  // ============================================================================
  // EMISSIVE CORE (Octahedron inside prism)
  // ============================================================================
  const octaGeom = new THREE.OctahedronGeometry(0.35, 2);
  const octaMat = new MeshBasicNodeMaterial({
    color: new THREE.Color('#ff2a38'),
    emissive: new THREE.Color('#ff2a38'),
    emissiveIntensity: 2.2,
    toneMapped: true
  });
  const octahedron = new THREE.Mesh(octaGeom, octaMat);
  octahedron.position.z = 0;
  prismGroup.add(octahedron);

  prismGroup.position.set(0, 0.3, 0);
  group.add(prismGroup);

  // ============================================================================
  // CAUSTIC STREAK (Floor plane with dispersed gradient)
  // ============================================================================
  const causticGeom = new THREE.PlaneGeometry(2.4, 0.5);
  const causticMat = new MeshBasicNodeMaterial({
    color: new THREE.Color('#ff2a38'),
    side: THREE.DoubleSide,
    transparent: true,
    opacity: 0.35,
    depthWrite: false
  });
  const caustic = new THREE.Mesh(causticGeom, causticMat);
  caustic.position.set(0, -1.1, 0.1);
  caustic.rotation.x = THREE.MathUtils.degToRad(-90);
  group.add(caustic);

  // ============================================================================
  // TEXT CONTENT
  // ============================================================================
  const headlineText = ctx.fontAtlas.createText('Light, machined.', {
    fontSize: 68,
    color: '#e8ecf2',
    align: 'center',
    letterSpacingPx: -3.4
  });
  headlineText.position.y = -1.75;
  headlineText.position.z = 0.1;
  group.add(headlineText);

  const captionText = ctx.fontAtlas.createText('SAPPHIRE OVER DIAL / ZERO DISTORTION', {
    fontSize: 18,
    color: '#9fb0c4',
    align: 'center',
    letterSpacingPx: 1.44
  });
  captionText.position.y = -2.25;
  captionText.position.z = 0.1;
  group.add(captionText);

  // ============================================================================
  // HOVER INTERACTION: depth-rotate
  // ============================================================================
  let depthRotateCleanup = null;

  group.userData.handlers = {
    onHover: () => {
      if (depthRotateCleanup) depthRotateCleanup();
      const result = ctx.primitives['depth-rotate'](prismGroup, { maxDeg: 10 });
      depthRotateCleanup = result.cleanup;
    },
    onUnhover: () => {
      if (depthRotateCleanup) {
        depthRotateCleanup();
        depthRotateCleanup = null;
      }
      // Weighted settle back to neutral
      gsap.to(prismGroup.rotation, {
        x: 0,
        y: THREE.MathUtils.degToRad(20),
        z: THREE.MathUtils.degToRad(12),
        duration: 0.9,
        ease: 'cubic-bezier(0.165,0.84,0.44,1)',
        overwrite: 'auto'
      });
    }
  };

  // ============================================================================
  // CLEANUP
  // ============================================================================
  group.userData.cleanup = () => {
    if (depthRotateCleanup) depthRotateCleanup();
    gsap.killTweensOf([prismGroup.rotation, prismGroup.position]);

    prismGeom.dispose();
    prismMat.dispose();
    octaGeom.dispose();
    octaMat.dispose();
    backdropGeom.dispose();
    backdropMat.dispose();
    causticGeom.dispose();
    causticMat.dispose();
  };

  return group;
}
